-- ==============================================================================
-- SCRIPT กู้คืนข้อมูลโรงงานตราเพชร (สิงหาคม 2569) - เวอร์ชัน SAFE & RESILIENT
-- ห้างหุ้นส่วนจำกัด วิราญกร
-- แก้ไข approved_by = NULL ป้องกัน foreign key error กับ profiles
-- ตรวจสอบ employee_id กับตาราง employees เสมอเพื่อป้องกัน foreign key error
-- ==============================================================================

BEGIN;

-- 1. ลบข้อมูลงวดและข้อมูลลูกของตราเพชรในเดือนสิงหาคมที่มีอยู่เดิม (ถ้ามี) เพื่อเตรียมรับข้อมูลใหม่
DELETE FROM public.shift_assignments 
WHERE period_id IN ('32538455-da39-41b7-bdea-06fa0685301f', '52756ed4-ba5d-4be6-9288-d0b365758342')
   OR (work_date >= '2026-08-01' AND work_date <= '2026-08-31'
       AND employee_id IN (SELECT id FROM public.employees WHERE factory_id = 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed'));

DELETE FROM public.payroll_entries 
WHERE period_id IN ('32538455-da39-41b7-bdea-06fa0685301f', '52756ed4-ba5d-4be6-9288-d0b365758342')
   OR employee_id IN (SELECT id FROM public.employees WHERE factory_id = 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed'
                      AND period_id IN (SELECT id FROM public.payroll_periods WHERE period_start >= '2026-08-01' AND period_end <= '2026-08-31'));

DELETE FROM public.advance_payments 
WHERE period_id IN ('32538455-da39-41b7-bdea-06fa0685301f', '52756ed4-ba5d-4be6-9288-d0b365758342')
   OR (period_id IN (SELECT id FROM public.payroll_periods WHERE factory_id = 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed'
                     AND period_start >= '2026-08-01' AND period_end <= '2026-08-31'));

DELETE FROM public.payroll_periods 
WHERE factory_id = 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed'
  AND period_start >= '2026-08-01' AND period_end <= '2026-08-31';

-- 2. นำเข้างวดทั้ง 2 งวด (1-15 ส.ค. 2569 [approved] และ 16-31 ส.ค. 2569 [draft])
-- ตั้ง approved_by เป็น NULL ป้องกันปัญหา Foreign Key กับ profiles เก่า
INSERT INTO public.payroll_periods (
  id, factory_id, label, period_start, period_end, status,
  approved_by, approved_at, social_security_rate, created_at
) VALUES
  ('32538455-da39-41b7-bdea-06fa0685301f', 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed', '1 - 15 สิงหาคม 2569', '2026-08-01', '2026-08-15', 'approved', NULL, NULL, 0.05, '2026-08-13T14:27:50.432828+00:00'),
  ('52756ed4-ba5d-4be6-9288-d0b365758342', 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed', '16 - 31 สิงหาคม 2569', '2026-08-16', '2026-08-31', 'draft', NULL, NULL, 0.05, '2026-08-25T14:05:41.860545+00:00')
ON CONFLICT (id) DO UPDATE SET
  label = EXCLUDED.label,
  period_start = EXCLUDED.period_start,
  period_end = EXCLUDED.period_end,
  status = EXCLUDED.status;

