-- ==============================================================================
-- ตรวจสอบผลลัพธ์หลังการกู้คืน (ต้องแสดง 2 งวดของสิงหาคม)
-- ==============================================================================
SELECT 
  p.id, 
  f.name AS factory_name, 
  p.label, 
  p.period_start, 
  p.period_end, 
  p.status, 
  (SELECT count(*) FROM public.shift_assignments sa WHERE sa.period_id = p.id) AS shifts_count,
  (SELECT count(*) FROM public.payroll_entries pe WHERE pe.period_id = p.id) AS payroll_entries_count,
  (SELECT count(*) FROM public.advance_payments ap WHERE ap.period_id = p.id) AS advances_count
FROM public.payroll_periods p
JOIN public.factories f ON f.id = p.factory_id
WHERE p.factory_id = 'de1616a9-33dc-4d20-bb0c-6e82cd0cc0ed'
ORDER BY p.period_start DESC;
